-- -----------------------------------------------------------------------------
-- 2. Containers
--
-- Staged first so codes are issued by next_container_code() in import order,
-- continuing from whatever already exists rather than restarting at SK-00001.
-- -----------------------------------------------------------------------------
select sync_container_code_seq();

create temp table osm_import (
    ordinal  int,
    osm_id   bigint,
    kind     text,
    category text,
    lon      double precision,
    lat      double precision
) on commit drop;

