-- Only rows we have never imported before (idempotent re-run).
insert into containers (code, kind, category, geom, source, osm_id,
                        verified, status, status_since, created_at)
select
    next_container_code(),
    o.kind,
    o.category,
    st_setsrid(st_makepoint(o.lon, o.lat), 4326)::geography,
    'osm',
    o.osm_id,
    -- OSM data is surveyed, not user-guessed: it starts verified (§4.6).
    true,
    'ok',
    now(),
    now()
from osm_import o
where not exists (
    select 1 from containers c where c.osm_id = o.osm_id
)
order by o.ordinal;

-- -----------------------------------------------------------------------------
-- 3. Assign municipality_id with ST_Contains (§7)
--
-- Runs over every container, not just the new ones, so re-running after the
-- boundaries land also fixes rows imported while geom was still NULL.
-- -----------------------------------------------------------------------------
update containers c
   set municipality_id = m.id
  from municipalities m
 where m.geom is not null
   and c.deleted_at is null
   and st_contains(m.geom::geometry, c.geom::geometry)
   and c.municipality_id is distinct from m.id;

-- Suggestions too, so city stats can group them (§5.4).
update suggestions s
   set municipality_id = m.id
  from municipalities m
 where m.geom is not null
   and st_contains(m.geom::geometry, s.geom::geometry)
   and s.municipality_id is distinct from m.id;

commit;

-- -----------------------------------------------------------------------------
-- 4. Check what landed
-- -----------------------------------------------------------------------------
select
    coalesce(m.name_en, '(unassigned)') as municipality,
    count(*) filter (where c.kind = 'big' and c.category = 'general') as big_general,
    count(*) filter (where c.kind = 'big' and c.category <> 'general') as recycling,
    count(*) filter (where c.kind = 'small') as small_cans,
    count(*) as total
from containers c
left join municipalities m on m.id = c.municipality_id
where c.source = 'osm' and c.deleted_at is null
group by m.name_en
order by total desc;
